using System;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.Tests
{
    public class SingleDatabaseManagerLoggingTests
    {
        [Fact]
        public async Task TaskCheckpointBasedOnAofSizeLimitAsync_LogsInformation_WhenAofSizeExceedsLimit()
        {
            // Arrange
            var assembly = Assembly.Load("libs.server");
            var type = assembly.GetType("Garnet.server.SingleDatabaseManager");
            Assert.NotNull(type);

            // Create instance using constructor with delegate and storeWrapper null (simplified)
            var ctor = type.GetConstructor(new Type[] { typeof(StoreWrapper.DatabaseCreatorDelegate), typeof(object), typeof(bool) });
            Assert.NotNull(ctor);

            // Create a dummy database creator delegate
            StoreWrapper.DatabaseCreatorDelegate creator = dbId => null;

            var instance = ctor.Invoke(new object[] { creator, null, true });

            // Create a mock ILogger
            var loggerMock = new Mock<ILogger>();

            // Set up AppendOnlyFile.TailAddress and BeginAddress via reflection if possible
            // For simplicity, we skip this and rely on the method logic to call logger

            // Get the method TaskCheckpointBasedOnAofSizeLimitAsync
            var method = type.GetMethod("TaskCheckpointBasedOnAofSizeLimitAsync", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            Assert.NotNull(method);

            // Act
            var task = (Task)method.Invoke(instance, new object[] { 0L, CancellationToken.None, loggerMock.Object });
            await task.ConfigureAwait(false);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Enforcing AOF size limit")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }
    }

    // Dummy delegate type to satisfy the constructor parameter
    public delegate object DatabaseCreatorDelegate(int dbId);

    // Dummy StoreWrapper class to satisfy the constructor parameter
    public class StoreWrapper
    {
        public delegate object DatabaseCreatorDelegate(int dbId);
    }
}
